function save(){try{localStorage.setItem('padova-game-v1',JSON.stringify({money:state.money,jobs:state.jobs,quality:state.quality,character:state.character}));}catch{}}
try{const s=JSON.parse(localStorage.getItem('padova-game-v1')||'{}');state.money=Number.isFinite(s.money)?Math.max(0,s.money):0;state.jobs=Number.isFinite(s.jobs)?s.jobs:0;state.quality=['low','medium','high'].includes(s.quality)?s.quality:'medium';state.character=CHARACTERS.some(c=>c.id===s.character)?s.character:'scando';}catch{}
function toast(t,seconds=3.5){$('toast').textContent=t;$('toast').hidden=false;toastUntil=state.elapsed+seconds;}
function progress(n,text){$('loadingBar').style.width=n+'%';$('loadingText').textContent=text;}
function yieldFrame(){return new Promise(r=>requestAnimationFrame(r));}

function setupGameplay(){
 if(gameplay)return;
 gameplay=new ModernGameplay({state,cars,people,cops,scene,terrain,graph:patrolGraph||graph,collision:world.collision,addCar,pose:poseVehicle,safeRoad:dryRoad,raiseWanted,defeat:explodePlayer,toast,
  forget:c=>previousActors.delete(c.mesh),remove:c=>{scene.remove(c.mesh);previousActors.delete(c.mesh);for(const pool of [cars,cops]){const i=pool.indexOf(c);if(i>=0)pool.splice(i,1);}if(c.police)c.mesh.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});}});
 parachute=createParachute();scene.add(parachute);
 PLACES[10]={...AIRPORT_GATE};if(!PLACES.some(p=>p.name===HOME.name))PLACES.push({...HOME});
}
function selectCharacter(id){const choice=CHARACTERS.find(c=>c.id===id)||CHARACTERS[0];state.character=choice.id;const old=player;player=createPerson(choice.color,choice.variant);player.position.set(state.x,state.y,state.z);player.rotation.y=state.yaw;scene.add(player);if(old){scene.remove(old);old.traverse(o=>{if(o.userData.clothing)o.material.dispose();});}}
function ejectParachute(){
 if(!state.started||state.paused||incidents?.recovery||!state.car?.spec.aircraft)return;
 if(state.y-terrain.height(state.x,state.z)<10){toast('Sali almeno 10 metri per aprire il paracadute.');return;}
 const c=state.car;c.parked=true;c.speed=0;c.abandonedAt=state.elapsed;c.mesh.visible=false;
 state.car=null;state.mode='foot';state.parachuting=true;state.speed=7;state.vy=-4;state.health=100;
 parachute.visible=true;parachute.position.set(state.x,state.y,state.z);player.visible=true;previousPose=null;cameraRig.reset(state.yaw);toast('Paracadute aperto · WASD per planare.',4);
}
function respawnAtVilla(){
 const wreck=state.car;if(wreck){wreck.health=0;wreck.speed=0;wreck.mesh.visible=false;wreck.destroyedUntil=state.elapsed+15;}
 cancelMission(false);clearPolice();state.car=null;state.mode='foot';state.parachuting=false;state.respawnHome=false;state.health=100;state.speed=0;state.vy=0;state.spin=state.knockX=state.knockZ=0;
 Object.assign(state,{x:HOME.x+4,z:HOME.z,yaw:HOME.yaw});state.y=terrain.height(state.x,state.z);state.waypoint=null;state.route=[];
 if(parachute)parachute.visible=false;waterRecovery.reset();waterRecovery.remember(state,terrain);document.body.classList.remove('water-fall');keys.clear();previousPose=null;
 player.position.set(state.x,state.y,state.z);player.visible=true;gameplay.graceUntil=state.elapsed+12;cameraRig.reset(state.yaw);camera.position.set(state.x,state.y+7,state.z-10);world.update(state.x,state.z,true);save();toast('Villa di Parco Treves · Salute ripristinata, ricercato azzerato.',5);
}

function compactCar(group){const positions=[],colors=[],normals=[];group.updateMatrixWorld(true);const inverseRoot=group.matrixWorld.clone().invert();const v=new THREE.Vector3(),n=new THREE.Vector3();const remove=[];group.traverse(o=>{if(!o.isMesh||o.material.transparent)return;const g=o.geometry,ind=g.index?.array,p=g.attributes.position,no=g.attributes.normal,c=o.material.color,nm=new THREE.Matrix3().getNormalMatrix(new THREE.Matrix4().multiplyMatrices(inverseRoot,o.matrixWorld));for(let j=0;j<(ind?.length||p.count);j++){const i=ind?ind[j]:j;v.fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld).applyMatrix4(inverseRoot);n.fromBufferAttribute(no,i).applyMatrix3(nm).normalize();positions.push(v.x,v.y,v.z);normals.push(n.x,n.y,n.z);colors.push(c.r,c.g,c.b);}remove.push(o);});for(const o of remove)o.parent?.remove(o);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.65}));mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return group;}
const vehicleStyles=[...Object.keys(NPC_VEHICLES),'mito','cinquecento','motorcycle','truck','scooter','sedan','sport','compact','wagon','utility'];
let helicopterTemplate;
function pooledHelicopter(){if(!helicopterTemplate){const g=createHelicopter(),{rotor,tailRotor}=g.userData;g.remove(rotor,tailRotor);compactCar(g);compactCar(rotor);compactCar(tailRotor);rotor.name='rotor';tailRotor.name='tailRotor';g.add(rotor,tailRotor);g.userData={};helicopterTemplate=g;}const g=helicopterTemplate.clone(true);g.userData.rotor=g.getObjectByName('rotor');g.userData.tailRotor=g.getObjectByName('tailRotor');return g;}
function poseVehicle(c){if(c.spec.aircraft){c.y??=terrain.height(c.x,c.z);c.mesh.position.set(c.x,c.y,c.z);c.mesh.rotation.set(-c.speed*.002,c.yaw,0,'YXZ');return;}c.y=terrain.height(c.x,c.z,c.y);c.mesh.position.set(c.x,c.y,c.z);const pitch=terrain.slope(c.x,c.z,c.yaw,c.spec.wheelbase,c.y);c.pitch=(c.pitch??pitch)+(pitch-(c.pitch??pitch))*.18;c.mesh.rotation.set(c.pitch,c.yaw,0,'YXZ');if(c.rider)c.rider.visible=c===state.car||!c.parked;}
function addCar(x,z,yaw=0,police=false,parked=false,requestedStyle=null){
 const palette=['#a92731','#567e7e','#c87358','#e4dbba','#48677b','#8f9b6f','#9b4e4a','#59606b','#d0d3ce'],index=cars.length,style=police?'sedan':requestedStyle||vehicleStyles[index%vehicleStyles.length],color=police?'#193b54':palette[index%palette.length];
 const m=SPECIAL_VEHICLES[style]?createSpecialVehicle(style):style==='airone'?pooledHelicopter():compactCar(NPC_VEHICLES[style]?createNPCCar(style,color):['mito','cinquecento','motorcycle','scooter','truck'].includes(style)?createVehicle(style,color):createCar(color,police,style)),spec=VEHICLES[style];
 const c={x,z,yaw,speed:0,health:100,mesh:m,police,parked,target:null,prev:null,name:police?'Polizia':spec.name,style,spec,path:[],pathIndex:0,routeAt:0,stuck:0};
 if(isBike(style)){c.rider=createRider();m.add(c.rider);}
 poseVehicle(c);scene.add(m);
 if(police){const mat=new THREE.MeshBasicMaterial({color:'#419cff'});const lamp=new THREE.Mesh(new THREE.BoxGeometry(.4,.18,.32),mat);lamp.position.set(-.35,1.84,-.15);m.add(lamp);c.lamp=lamp;c.beacon=new THREE.PointLight('#298aff',0,13,2);c.beacon.position.set(0,2,0);m.add(c.beacon);cops.push(c);}else cars.push(c);return c;
}
function dryRoad(pos,spec=null,ignore=state.car){return safeDryRoad(pos,graph,world.collision,terrain,spec,p=>![...cars,...cops].some(c=>c!==ignore&&c.mesh.visible&&dist(c,p)<(c.spec.length+(spec?.length||1))/2+1));}
function vehiclesMenu(){if(!state.started||waterRecovery.active||incidents?.recovery)return;showMenu('Choose a vehicle','<p class="about-copy">Bring a vehicle to a clear road nearby. E to get in. V opens this menu.</p><div class="activities">'+['mito','cinquecento','motorcycle','scooter','truck'].map(type=>'<button class="activity" data-vehicle="'+type+'"><span><b>'+VEHICLES[type].name+'</b><small>'+Math.round(VEHICLES[type].max*3.6)+' km/h · '+VEHICLES[type].length+' m</small></span></button>').join('')+'</div>');document.querySelectorAll('[data-vehicle]').forEach(button=>button.onclick=()=>{
 const type=button.dataset.vehicle,spec=VEHICLES[type];let p=null;
 for(const offset of [12,24,40,70]){const candidate=dryRoad({x:state.x+Math.sin(state.yaw)*offset,z:state.z+Math.cos(state.yaw)*offset},spec);if(candidate&&dist(candidate,state)>spec.length/2+3&&![...cars,...cops].some(c=>c.mesh.visible&&dist(c,candidate)<(c.spec.length+spec.length)/2+2)){p=candidate;break;}}
 if(!p){toast('No clear space nearby. Move to a wider road.');return;}
 let c=cars.find(c=>c!==state.car&&c.style===type);if(!c)c=addCar(p.x,p.z,p.yaw,false,true,type);c.x=p.x;c.z=p.z;c.y=p.y??terrain.height(p.x,p.z);c.yaw=p.yaw;c.speed=0;c.health=100;c.parked=true;c.mesh.visible=true;poseVehicle(c);previousActors.delete(c.mesh);closeDialogs();state.waypoint={x:c.x,z:c.z,name:c.name};routeTo(state.waypoint);toast(c.name+' is waiting '+Math.round(dist(state,c))+' m away. Follow the marker.',5);
 });}
function goodNearbyNode(pos,minD=50,maxD=500,spec=null,style=null){const candidates=[],seen=new Set();let total=0;
 for(const s of graph.index.near(pos.x,pos.z,maxD)){const road=s.road;if(!s.connected||road.w<(spec?.length>6?7:spec?4:0)||['no','private'].includes(road.access)||spec&&road.k==='pedestrian'||!spec&&/motorway|trunk/.test(road.k))continue;
  for(const id of [s.a,s.b]){if(seen.has(id))continue;seen.add(id);const n=graph.nodes[id],d=dist(n,pos);if(d<=minD||d>=maxD||!n.edges.length)continue;
   const zone=DISTRICTS[districts?.at(n.x,n.z,road)||'urban'],weight=spec?zone.traffic*(style?(zone.vehicles.includes(style)?3:.1):1):zone.people;
   if(weight<=0)continue;total+=weight;candidates.push({id,end:total});}}
 const r=Math.random()*total;return candidates.find(p=>r<p.end)?.id??null;
}
const trafficModels=new Map();
function restyleTraffic(c,zone){if(c.police||c.parked)return;const legacy=DISTRICTS[zone].vehicles,style=Math.random()<.2?legacy[Math.floor(Math.random()*legacy.length)]:chooseTrafficStyle(zone);if(style===c.style)return;
 if(!trafficModels.has(style)){const color=['#a92731','#667d7d','#c9c1ac','#687688'][Math.max(0,vehicleStyles.indexOf(style))%4],m=compactCar(NPC_VEHICLES[style]?createNPCCar(style,color):['mito','cinquecento','scooter','motorcycle','truck'].includes(style)?createVehicle(style,color):createCar(color,false,style));trafficModels.set(style,m);}
 const old=c.mesh;scene.remove(old);previousActors.delete(old);c.mesh=trafficModels.get(style).clone(true);scene.add(c.mesh);c.style=style;c.spec=VEHICLES[style];c.name=c.spec.name;c.rider=null;if(isBike(style)){c.rider=createRider();c.mesh.add(c.rider);}
}
function placeTraffic(c,minD=100,maxD=550){const id=goodNearbyNode(state,minD,maxD,c.spec,c.style);if(id===null){c.mesh.visible=false;return;}const n=graph.nodes[id];restyleTraffic(c,districts?.at(n.x,n.z,n.edges[0]?.road)||'urban');c.x=n.x;c.z=n.z;c.prev=id;c.target=n.edges[Math.floor(Math.random()*n.edges.length)]?.id;c.stuck=0;c.speed=0;c.driver=.8+Math.random()*.35;if(c.target!==undefined){const t=graph.nodes[c.target];c.yaw=Math.atan2(t.x-c.x,t.z-c.z);}const safe=dryRoad(c,c.spec,c);if(!safe||[...cars,...cops].some(other=>other!==c&&other.mesh.visible&&dist(c,other)<(c.spec.length+other.spec.length)/2+2)){c.mesh.visible=false;return;}c.x=safe.x;c.z=safe.z;c.yaw=safe.yaw;c.y=terrain.roads.sample(safe.segment.road,c.x,c.z)+.05;c.road=safe.segment.road;const reverse=c.road.oneway===-1;c.prev=reverse?safe.segment.b:safe.segment.a;c.target=reverse?safe.segment.a:safe.segment.b;c.mesh.visible=true;poseVehicle(c);}
function createPopulation(){
 if(data.gameplay){Object.assign(state,{x:HOME.x,z:HOME.z,yaw:HOME.yaw});setupGameplay();}
 const initial=dryRoad(state,VEHICLES.mito);if(initial){state.x=initial.x-3*Math.cos(initial.yaw);state.z=initial.z+3*Math.sin(initial.yaw);if(collides(state.x,state.z,.35,world.collision)||!terrain.dry(state.x,state.z,1)){state.x=initial.x;state.z=initial.z;}state.yaw=initial.yaw;addCar(initial.x,initial.z,initial.yaw,false,true,'mito');state.y=terrain.height(state.x,state.z,state.y);waterRecovery.remember(state,terrain);}
 const count=state.quality==='low'?16:state.quality==='high'?48:30;for(let i=0;i<count;i++){const c=addCar(0,0,0,false,i<3);placeTraffic(c,60,520);}
 const population=state.quality==='low'?40:state.quality==='high'?120:72;for(let i=0;i<population;i++){const p={x:0,z:0,yaw:0,seed:i,mesh:createPerson(['#d2b487','#719085','#bc745a','#527789','#c18c77','#6f789b'][i%6],i),at:0};scene.add(p.mesh);people.push(p);placePerson(p);}
 for(const pad of helicopterPads(terrain,world.collision,HELICOPTER).filter(p=>!data.gameplay||p.name!=='Aeroporto')){const c=addCar(pad.x,pad.z,0,false,true,'airone');c.y=pad.y;c.home=pad;c.fixedSpawn=true;c.name+=' · '+pad.name;poseVehicle(c);}
 gameplay?.populate();
}
function placePerson(p){if(p.koUntil>state.elapsed)return;p.health=100;p.koUntil=0;p.at=state.elapsed+4+Math.random()*8;p.mesh.visible=false;
 for(let attempt=0;attempt<16;attempt++){const id=goodNearbyNode(state,25,240);if(id===null)return;const n=graph.nodes[id],e=n.edges.find(e=>!/motorway|trunk/.test(e.road.k));if(!e)continue;
  const t=graph.nodes[e.id],yaw=Math.atan2(t.x-n.x,t.z-n.z),side=p.seed%2?1:-1,offset=e.road.k==='pedestrian'?1:e.road.w/2+1.25,u=.15+Math.random()*.7;
  const x=n.x+(t.x-n.x)*u+Math.cos(yaw)*offset*side,z=n.z+(t.z-n.z)*u-Math.sin(yaw)*offset*side;
  const zone=DISTRICTS[districts?.at(x,z,e.road)||'urban'];if(Math.random()>Math.min(1,zone.people/1.5))continue;
  if(collides(x,z,.4,world.collision)||!terrain.dry(x,z,.6))continue;
  Object.assign(p,{x,z,y:terrain.height(x,z),yaw,roadYaw:yaw,side,behavior:['destination','stroll','idle','cross','wait','group','runner','wander','avoid','poi'][p.seed%10],crossGoal:null,destination:{x:t.x+Math.cos(yaw)*offset*side,z:t.z-Math.sin(yaw)*offset*side},road:e.road,anchor:{x,z},knockX:0,knockZ:0,spin:0});p.mesh.visible=true;if(p.behavior==='poi'){const poi=PLACES.find(a=>dist(a,p)<40);if(poi)p.destination={x:poi.x,z:poi.z};}p.at=state.elapsed+18+Math.random()*24;
  const color=zone.colors[p.seed%zone.colors.length];if(p.mesh.userData.clothesColor!==color){p.mesh.traverse(o=>{if(o.userData.clothing)o.material.color.set(color);});p.mesh.userData.clothesColor=color;}return;
 }
}

function makeMap(){mapBase=document.createElement('canvas');mapBase.width=1800;mapBase.height=1740;mapCtx=mapBase.getContext('2d');const c=mapCtx,sx=mapBase.width/minBounds.w,sz=mapBase.height/minBounds.h;c.fillStyle='#1d333c';c.fillRect(0,0,mapBase.width,mapBase.height);const path=(p,close=false)=>{c.beginPath();p.forEach((p,i)=>{const x=(p[0]-minBounds.x)*sx,y=(p[1]-minBounds.z)*sz;if(!i)c.moveTo(x,y);else c.lineTo(x,y);});if(close)c.closePath();};
 for(const a of data.areas){path(a.p,true);c.fillStyle=a.k==='water'?'#33545d':'#284b42';c.fill();}for(const r of data.water){path(r.p);c.strokeStyle='#335d69';c.lineWidth=Math.max(1,r.w*sx);c.stroke();}c.fillStyle='#33474d';for(const b of data.buildings){path(b.p,true);c.fill();}for(const r of data.roads){path(r.p);c.lineWidth=Math.max(.5,r.w*sx);c.strokeStyle=['footway','path','steps'].includes(r.k)?'#405158':'#607278';c.stroke();}
}
function drawRoute(ctx,transform,width=3){if(!state.route.length)return;ctx.beginPath();state.route.forEach((p,i)=>{const a=transform(p);if(!i)ctx.moveTo(a.x,a.y);else ctx.lineTo(a.x,a.y);});ctx.strokeStyle='#edbb65';ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();}
function drawMini(){if(!mapBase)return;const c=miniCtx,w=mini.width,h=mini.height,range=state.mode==='car'?530:320,k=w/range;c.fillStyle='#172e38';c.fillRect(0,0,w,h);const mx=(state.x-minBounds.x)/minBounds.w*mapBase.width,my=(state.z-minBounds.z)/minBounds.h*mapBase.height,sw=range/minBounds.w*mapBase.width,sh=h/k/minBounds.h*mapBase.height;c.drawImage(mapBase,mx-sw/2,my-sh/2,sw,sh,0,0,w,h);const tr=p=>({x:(p.x-state.x)*k+w/2,y:(p.z-state.z)*k+h/2});drawRoute(c,tr,5);
 for(const p of PLACES){const t=tr(p);if(t.x>5&&t.x<w-5&&t.y>10&&t.y<h-5){c.fillStyle='#c6b28c';c.beginPath();c.arc(t.x,t.y,4,0,Math.PI*2);c.fill();}}
 for(const c of cars)if((c.spec.aircraft||c.spec.tracked)&&c.mesh.visible){const t=tr(c);if(t.x>8&&t.x<w-8&&t.y>8&&t.y<h-8){miniCtx.fillStyle='#edbb65';miniCtx.font='bold 14px sans-serif';miniCtx.fillText(c.spec.tracked?'T':c.spec.plane?'A':'H',t.x,t.y);}}
 for(const p of cops){const t=tr(p);c.fillStyle='#76b7ff';c.beginPath();c.arc(t.x,t.y,5,0,Math.PI*2);c.fill();}const target=currentTarget();if(target){const t=tr(target);c.fillStyle='#ffc56a';c.beginPath();c.arc(clamp(t.x,10,w-10),clamp(t.y,10,h-10),7,0,Math.PI*2);c.fill();}
 c.save();c.translate(w/2,h/2);c.rotate(-state.yaw);c.fillStyle='#fff8de';c.strokeStyle='#18323d';c.lineWidth=2;c.beginPath();c.moveTo(0,11);c.lineTo(-7,-7);c.lineTo(0,-3);c.lineTo(7,-7);c.closePath();c.fill();c.stroke();c.restore();c.fillStyle='#bbcbd0';c.font='600 20px system-ui';c.fillText('N',w-28,26);
}
function fullTransform(p){const c=$('fullmap');return {x:(p.x-minBounds.x)/minBounds.w*c.width,y:(p.z-minBounds.z)/minBounds.h*c.height};}
