 if(state.car){Object.assign(state.car,{x:p.x,z:p.z,yaw:p.yaw,speed:0,health:100,knockX:0,knockZ:0,spin:0,turboTime:0,y:state.y,vy:0});poseVehicle(state.car);previousActors.delete(state.car.mesh);}
