 const goal=Math.atan2(target.x-c.x,target.z-c.z),diff=angleDiff(goal,c.yaw),newYaw=c.yaw+clamp(diff,-2.4*dt,2.4*dt),limit=Math.abs(diff)>.6?5:clamp(d*.45,5,23+state.wanted*3);
 let desired=limit;for(const other of cops)if(other!==c&&dist(c,other)<7&&Math.abs(angleDiff(Math.atan2(other.x-c.x,other.z-c.z),c.yaw))<.6)desired=0;
