function explodePlayer(reason){if(incidents?.recovery)return;state.respawnHome=state.wanted===5||state.mode==='foot';if(!incidents?.explode(state,state.elapsed,reason))return;state.speed=0;state.health=0;state.spin=state.knockX=state.knockZ=0;keys.clear();if(state.car){state.car.health=0;state.car.mesh.visible=false;}if(state.respawnHome){cancelMission(false);clearPolice();}toast(reason+(state.respawnHome?' · Ritorno alla villa…':' · Recovering nearby…'),2);}
