function pauseMenu(){if(!state.ready)return;showMenu('Take a breather.','<div class="controls-grid"><span><kbd>W / S</kbd> accelerate / reverse</span><span><kbd>A / D</kbd> steer / move sideways</span><span><kbd>E</kbd> enter / leave vehicle</span><span><kbd>V</kbd> choose a vehicle</span><span><kbd>SPACE</kbd> brake / jump</span><span><kbd>SHIFT</kbd> boost / sprint</span><span><kbd>TAB</kbd> Turbo Cinquecento / cannone carro</span><span><kbd>F</kbd> paracadute in volo</span><span>Volo: W accelera · SPACE sale · SHIFT scende</span><span><kbd>C</kbd> cycle camera</span><span><kbd>M</kbd> city map</span><span><kbd>J</kbd> activities</span><span><kbd>R</kbd> recover & repair</span><span>On foot: WASD follows the camera. Drag to look.</span></div><div class="settings"><label for="quality">Graphics</label><select id="quality"><option value="low">Performance</option><option value="medium">Balanced</option><option value="high">Detailed</option></select><button id="soundBtn" class="textbutton">Sound: '+(state.sound?'on':'off')+'</button></div><p class="about-copy">'+state.jobs+' jobs completed · €'+Math.floor(state.money)+' earned<br>Progress is saved on this browser. Traffic density updates after reloading.<br>Scene: '+renderer.info.render.calls+' draw calls · '+Math.round(renderer.info.render.triangles/1000)+'k triangles.</p><div class="menu-actions"><button class="primary" id="resumeBtn">'+(state.started?'Back to the streets':'Close')+'</button><button id="recoverBtn">Recover vehicle</button><button id="fullscreenBtn">Full screen</button><button id="vehiclesBtn">Choose a vehicle</button><button id="worldInfoBtn">About the world</button></div>');$('quality').value=state.quality;$('quality').onchange=e=>{state.quality=e.target.value;applyQuality();save();};$('resumeBtn').onclick=closeDialogs;$('recoverBtn').onclick=()=>{recover();closeDialogs();};$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use your browser’s full-screen control.');}};$('worldInfoBtn').onclick=about;$('vehiclesBtn').onclick=vehiclesMenu;$('soundBtn').onclick=()=>{state.sound=!state.sound;if(state.sound)initAudio();$('soundBtn').textContent='Sound: '+(state.sound?'on':'off');};}
function about(){const buildings=data?.buildings.length.toLocaleString('en-GB')||'88,000';showMenu('Padova, at street scale.','<div class="about-copy"><p><strong>A playable, stylised reconstruction of Padua.</strong> '+buildings+' mapped building footprints, real streets, waterways and parks across a roughly 13 × 13 km area. One metre in the map is one metre in the game.</p><p>Street geometry and building footprints come from <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> (ODbL). Building heights are estimated where the map has no height data. Facades and landmark details are interpretive. Terrain follows an offline, smoothed elevation grid without exaggeration. Bridge ramps and river levels are approximate. Water causes a fall and automatic recovery; bridges remain usable.</p><p>Elevation: <a href="https://github.com/tilezen/joerd/blob/master/docs/attribution.md" target="_blank" rel="noopener">Mapzen Terrain Tiles · Copernicus EU-DEM · USGS</a>. <a href="./data/terrain.json" download>Download the derived terrain data</a>.</p><p>Buildings with supplied GLB models replace their map extrusions automatically. The remaining city is still approximate; a complete photographic centre is not included.</p><p>This version has outdoor exploration, driving, traffic, courier jobs, checkpoint races and police pursuits. It does not contain photographic buildings, complex interiors, multiplayer or GTA’s full systems.</p><p>Best on a MacBook with a keyboard. Use <strong>Performance</strong> graphics if movement feels slow. Drag on the scene to look around; no mouse lock needed.</p><p>Built with <a href="https://threejs.org" target="_blank" rel="noopener">Three.js</a> · <a href="./data/padova.json" download>Download the derived map data</a> · <a href="./model-guide.html" target="_blank" rel="noopener">Add real buildings</a></p></div><div class="menu-actions"><button class="primary" id="aboutClose">Back</button></div>');$('aboutClose').onclick=closeDialogs;}
